import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"16、【豫】 坤下震上","description":"周易集注 - 16、【豫】 坤下震上","frontmatter":{"title":"16、【豫】 坤下震上","description":"周易集注 - 16、【豫】 坤下震上"},"headers":[],"relativePath":"zh/classics/jizhu/020.md","filePath":"zh/classics/jizhu/020.md"}'),h={name:"zh/classics/jizhu/020.md"};function t(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_16、【豫】-坤下震上" tabindex="-1">16、【豫】 坤下震上 <a class="header-anchor" href="#_16、【豫】-坤下震上" aria-label="Permalink to “16、【豫】 坤下震上”">​</a></h1><p>豫者和乐也，阳始潜闭于地中，及其动而出地，奋发其声，通畅和豫，豫之象也。内顺外动，豫之由也。《序卦》“有大而能谦必豫，故受之以豫”，所以次谦。</p><p>震长子主器，震惊百里，建侯之象。中爻坎陷，一阳统众阴，行师之象。屯有震无坤，则言建侯，谦有坤无震，则言行师，此震坤合故兼言也。</p><p>《彖》曰：豫刚应而志行，顺以动，豫。豫顺以动，故天地如之，而况建侯行师乎。天地以顺动，故日月不过，而四时不忒。圣人以顺动，则刑罚清而民服，豫之时义大矣哉。</p><p>以卦体卦德释卦名卦辞，而极言之。刚九四也，刚应者，一阳而众阴从之也。志行者，阳之志得行也。刚应志行豫也，内顺外动，所以成其豫也，故名豫。人事合乎天理则顺，背乎天理则逆，顺以动则一念一事皆天理矣。天地如之者，言天地亦不过如我之顺动也。天地且不之违，而况于人之建侯行师乎。此其所以利也。建侯行师虽大事，较之天地则小矣。天地以顺动者，顺其自然之气;圣人以顺动者，顺其当然之理。不过者，不差过也，如夏至昼六十刻夜四十刻，冬至昼四十刻夜六十刻之类是也。不忒者，不愆忒也，如夏则暑，冬则寒之类是也。刑罚不合乎理，惟乘一己喜怒之私，故民不服。若顺动合乎天理之公，纵施刑罚，亦天刑也，故民服。时义者，豫中事理之时宜也，即顺动也，此极言而赞之也。六十四卦时而已矣，事若浅而有深意，曰时义大矣哉，欲人思之也。非美事有时或用之，曰时用大矣哉，欲人则之也。大事大变曰时大矣哉，欲人谨之也。</p><h3 id="《象》曰-雷出地奋-豫。先王以作乐崇德-殷荐之上帝-以配祖考。" tabindex="-1">《象》曰：雷出地奋，豫。先王以作乐崇德，殷荐之上帝，以配祖考。 <a class="header-anchor" href="#《象》曰-雷出地奋-豫。先王以作乐崇德-殷荐之上帝-以配祖考。" aria-label="Permalink to “《象》曰：雷出地奋，豫。先王以作乐崇德，殷荐之上帝，以配祖考。”">​</a></h3><p>奋者，奋发而成声也。作，乃制礼作乐之作，作乐以崇德，故闻乐知德。殷，盛也，作乐乃朝廷邦国之常典，各有所主，其乐不同，惟万物本乎天，故有郊，人本乎祖，故有庙，是其用乐之最大者，故曰殷荐。故冬至祀上帝于圜丘，而配之以祖，必以是乐荐之。季秋祀上帝于明堂，而配之以考，必以是乐荐之。卦中爻坎为乐律，乐之象，五阴而崇一阳德，崇德之象。帝出于震，上帝之象，中爻艮为门阙，坎为隐伏，宗庙祖宗之象。</p><p>初六，鸣豫，凶。</p><p>鸣，详见鸣谦。谦豫二卦同体，文王综为一卦，故《杂卦》曰“谦轻而豫怠也”。谦之上六，即豫之初六，故二爻皆言鸣。震性动又决躁，所以浚恒凶，飞鸟凶。</p><p>初六与九四为正应，九四由豫，初据其应与之常，欲相从乎四而和之，故有鸣豫之象。然初位卑，四近君，乃权臣也。正其志大行之时，上下既悬绝，且初又不中正，应与之情乖矣，岂能与四彼此唱和?其豫不能唱和，初之志穷矣，凶之道也，故占者凶。</p><h3 id="《象》曰-初六鸣豫-志穷凶也。" tabindex="-1">《象》曰：初六鸣豫，志穷凶也。 <a class="header-anchor" href="#《象》曰-初六鸣豫-志穷凶也。" aria-label="Permalink to “《象》曰：初六鸣豫，志穷凶也。”">​</a></h3><p>惟志穷所以凶。中孚鹤鸣子和，曰中心愿也，六二鸣谦，曰中心得也，此心志相孚者也。上六鸣谦，曰志未得也，初六鸣豫，曰志穷凶也，此心志不相孚者也。相孚者皆曰心，不相孚者皆曰志，此所以为圣人之言。</p><p>六二，介于石，不终日，贞吉。</p><p>凡物分为两间者曰介，二变刚，分坤为两间，介之象也。介于石者，言操守之坚，如石不可移易，中爻艮石之象也。不终日者，不溺于豫，见几而作，不待其日之晚也。二变，中爻离，且居下卦之上，不终日之象也。八卦正位，坤在二，故贞吉。</p><p>豫易以溺人，诸爻皆溺于豫，独六二中正自守，安静坚确，故有此象，正而且吉之道也，故其占如此。</p><h3 id="《象》曰-不终日-贞吉-以中正也。" tabindex="-1">《象》曰：不终日，贞吉，以中正也。 <a class="header-anchor" href="#《象》曰-不终日-贞吉-以中正也。" aria-label="Permalink to “《象》曰：不终日，贞吉，以中正也。”">​</a></h3><p>惟中正，故不终日贞吉。</p><p>六三，盱豫，悔迟有悔。</p><p>盱者，张目也。中爻错离，目之象也。盱目以为豫者，九四当权，三与亲比，幸其权势之足凭，而自纵其所欲也。盱与介相反，迟与不终日相反。二中正，三不中正故也。</p><p>四为豫之主，六三阴柔，不中不正，而近于四，上视于四，而溺于豫，宜有悔者也，故有此象。而其占为事当速悔，若悔之迟，则过而不改，是谓过矣。此圣人为占者开迁善之门，而勉之以速改也。</p><h3 id="《象》曰-盱豫有悔-位不当也。" tabindex="-1">《象》曰：盱豫有悔，位不当也。 <a class="header-anchor" href="#《象》曰-盱豫有悔-位不当也。" aria-label="Permalink to “《象》曰：盱豫有悔，位不当也。”">​</a></h3><p>六三不中不正，故位不当。</p><p>九四，由豫，大有得，勿疑，朋盍簪。</p><p>由豫者，言人心之和豫，由四而致也。本卦一阳为动之主，动而众阴悦从，故曰由豫。大有得者，言得大行其志，以致天下之豫也。四多疑惧，故曰疑。又中爻坎，亦为狐疑。勿疑者，中爻艮止，止而不疑之象也。因九四才刚明，故教之以勿疑也。盍者合也，簪者首笄也，妇人冠上之饰，所以緫聚其髪者也。下坤，妇人之象也，一阳横于三阴之首，簪之象也。勿疑朋盍簪者，勿疑朋合于我者，皆簪冠之妇人也。</p><p>九四一阳居五阴之中，人所由以为豫，故有由豫之象。占者遇此，故为大有得。然人既乐从，正当得志之时，必展其大行之志，俾人人皆享其和平豫大之福，勿疑由豫于我者，无同德之阳明而所以朋合于上下内外者，皆阴柔之群小可也。故又教占者，必不可疑如此。</p><h3 id="《象》曰-由豫-大有得-志大行也。" tabindex="-1">《象》曰：由豫，大有得，志大行也。 <a class="header-anchor" href="#《象》曰-由豫-大有得-志大行也。" aria-label="Permalink to “《象》曰：由豫，大有得，志大行也。”">​</a></h3><p>刚应而无他爻以分其权，故曰志大行。</p><p>六五，贞疾，恒不死。</p><p>中爻为坎，坎为心病，疾之象也。曰贞疾者，言非假疾，疾之在外而可以药石者也。九四由豫，人心通归于四，危之极矣。下卦坤为腹，凡四居卦之中为心，即咸卦憧憧往来之爻也。此正腹中心疾，故谓之贞疾。恒者常也，言贞疾而常不死也。周室衰微，此爻近之。</p><p>六五当豫之时，柔不能立，而又乘九四之刚，权之所主，众之所归，皆在于四。衰弱极矣，故有贞疾之象。然以其得中，故又有恒不死之象。即象而占可知矣。</p><h3 id="《象》曰-六五贞疾-乘刚也。恒不死-中未亡也。" tabindex="-1">《象》曰：六五贞疾，乘刚也。恒不死，中未亡也。 <a class="header-anchor" href="#《象》曰-六五贞疾-乘刚也。恒不死-中未亡也。" aria-label="Permalink to “《象》曰：六五贞疾，乘刚也。恒不死，中未亡也。”">​</a></h3><p>虽乘四，为刚所逼，然柔而得中，犹存虚位不死。</p><p>上六，冥豫，成有渝，无咎。</p><p>冥者，幽也，暗也。上六以阴柔居豫极，为昏冥于豫之象。成者，五阴同豫，至上六已成矣，然以动体变刚成离，则前之冥冥者今反昭昭矣，故又为其事虽成，然乐极哀生，不免有悔心之萌，而能改变之象。占者如是，则能补过矣，故无咎。</p><h3 id="《象》曰-冥豫在上-何可长也。" tabindex="-1">《象》曰：冥豫在上，何可长也。 <a class="header-anchor" href="#《象》曰-冥豫在上-何可长也。" aria-label="Permalink to “《象》曰：冥豫在上，何可长也。”">​</a></h3><p>豫已极矣，宜当速改，何可长溺于豫而不返也。</p>',36)])])}const f=e(h,[["render",t]]);export{_ as __pageData,f as default};
